import pyomo.environ as pyo

DATA = {
    "FOODS": ["Chicken", "Rice", "Vegetables", "Bread", "Almonds", "Salmon"],
    "NUTRIENTS": ["protein", "carbs", "calories"],
    # cost per serving ($)
    "cost": {
        "Chicken": 2,
        "Rice": 3,
        "Vegetables": 3,
        "Bread": 2,
        "Almonds": 4,
        "Salmon": 10,
    },
    # nutrient content per serving
    "content": {
        "protein": {
            "Chicken": 16, "Rice": 11, "Vegetables": 1,
            "Bread": 6, "Almonds": 2, "Salmon": 19,
        },
        "carbs": {
            "Chicken": 8, "Rice": 24, "Vegetables": 5,
            "Bread": 26, "Almonds": 11, "Salmon": 20,
        },
        "calories": {
            "Chicken": 50, "Rice": 90, "Vegetables": 164,
            "Bread": 165, "Almonds": 51, "Salmon": 238,
        },
    },
    # minimum requirements
    "requirement": {
        "protein": 58,
        "carbs": 150,
        "calories": 2392,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["FOODS"])
    model.NUTRIENTS = pyo.Set(initialize=d["NUTRIENTS"])

    # Decision: servings of each food
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # One constraint per nutrient: meet the minimum requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.FOODS) >= d["requirement"][n]
    model.nutrient = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


